class Solution {
    public int minCostSetTime(int startAt, int moveCost, int pushCost, int targetSeconds) {
        int m = targetSeconds / 60, s = targetSeconds % 60;
        return Math.min(getCost(m, s, startAt, moveCost, pushCost),
                        getCost(m - 1, s + 60, startAt, moveCost, pushCost));
    }
    private int getCost(int m, int s, int startAt, int moveCost, int pushCost) {
        if (m < 0 || m > 99 || s < 0 || s > 99) return Integer.MAX_VALUE;
        String str = String.valueOf(m * 100 + s);
        int cost = 0;
        char cur = (char) ('0' + startAt);
        for (char ch : str.toCharArray()) {
            if (ch != cur) {
                cost += moveCost;
                cur = ch;
            }
            cost += pushCost;
        }
        return cost;
    }
}

var minCostSetTime = function(startAt, moveCost, pushCost, targetSeconds) {
    const getCost = (m, s) => {
        if (m < 0 || m > 99 || s < 0 || s > 99) return 1e9;
        const str = String(m * 100 + s);
        let cost = 0, cur = String(startAt);
        for (const ch of str) {
            if (ch !== cur) {
                cost += moveCost;
                cur = ch;
            }
            cost += pushCost;
        }
        return cost;
    };
    const m = Math.floor(targetSeconds / 60), s = targetSeconds % 60;
    return Math.min(getCost(m, s), getCost(m - 1, s + 60));
};
